'use server';

import { revalidatePath } from 'next/cache';
import fs from 'node:fs/promises';
import path from 'node:path';

const DB_PATH = path.join(process.cwd(), 'db.json');

export async function toggleNotifications() {
  const fileContent = await fs.readFile(DB_PATH, 'utf-8');
  const data = JSON.parse(fileContent);

  data.notificationsEnabled = !data.notificationsEnabled;

  await fs.writeFile(DB_PATH, JSON.stringify(data, null, 2));

  // This refreshes the page's data without a redirect
  revalidatePath('/');
}

import fs from 'node:fs/promises';
import path from 'node:path';
import { toggleNotifications } from './actions';

export default async function Home() {
  // Read current state from db.json
  const fileContent = await fs.readFile(path.join(process.cwd(), 'db.json'), 'utf-8');
  const { notificationsEnabled } = JSON.parse(fileContent);

  return (
    <main>
      <h1>Notification Settings</h1>

      <p>Current Status: <strong>{notificationsEnabled ? 'Enabled' : 'Disabled'}</strong></p>

      <form action={toggleNotifications}>
        <button type="submit">
          Toggle Notifications
        </button>
      </form>
    </main>
  );
}

